'use strict';
document.querySelectorAll('[data-carousel]').forEach(region=>{const track=region.querySelector('[data-carousel-track]'),prev=region.querySelector('[data-carousel-prev]'),next=region.querySelector('[data-carousel-next]');if(!track)return;const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;function update(){prev.disabled=track.scrollLeft<4;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-4}function move(direction){const card=[...track.children].find(n=>!n.hidden);if(!card)return;const gap=parseFloat(getComputedStyle(track).columnGap)||0;track.scrollBy({left:direction*(card.getBoundingClientRect().width+gap),behavior:reduced()?'instant':'smooth'})}prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',update,{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}else if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});new ResizeObserver(update).observe(track);const filters=[...region.querySelectorAll('[data-home-news-filter]')];filters.forEach(b=>b.addEventListener('click',()=>{filters.forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',String(f===b))});const cat=b.dataset.homeNewsFilter;[...track.children].forEach(card=>card.hidden=cat!=='all'&&card.dataset.newsType!==cat);track.scrollTo({left:0,behavior:'instant'});const count=region.querySelector('.carousel-count');if(count)count.textContent=[...track.children].filter(c=>!c.hidden).length+BMDI18n.t(' stories');update()}));update()});
